#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> v = {10, 50, 20, 40};

    // 1. Iterator arithmetic (RAI feature)
    auto it = v.begin();
    it += 2; // Jump two positions in O(1)
    std::cout << *it << "\n"; // Output: 20

    // 2. Efficient algorithm use (std::sort requires RAI for N log N)
    std::sort(v.begin(), v.end());

    // 3. Indexing via iterator (RAI feature)
    std::cout << v.begin()[3] << std::endl; // Output: 40
}
